export type BookSetup = {
  id: string;
  label: string;
  costUsd: number | null;
  sessions: number;
  survivingChanges: number;
  unattendedShare: number;
};

export type BookInput = {
  periodDays: number;
  setups: BookSetup[];
  promoted: string | null;
  assumptions: { engineerMonthlyLoadedUsd: number; scaleSessionsPerWeek: number };
};

export type BookOutput = {
  department: {
    setup: string;
    label: string;
    monthlySpendUsd: number | null;
    survivingChangesPerMonth: number;
    costPerSurvivingChangeUsd: number | null;
    unattendedPct: number;
  }[];
  scenario: {
    hireMonthlyUsd: number;
    scaleMonthlyUsd: number | null;
    scaleSurvivingChangesPerMonth: number | null;
  };
  assumptions: Record<string, number>;
};

const cents = (n: number): number => Math.round(n * 100) / 100;
const tenth = (n: number): number => Math.round(n * 10) / 10;

export function buildBook(input: BookInput): BookOutput {
  const { periodDays, setups, promoted, assumptions } = input;
  const toMonth = (v: number): number => (v * 30) / periodDays;

  const department = setups.map((s) => {
    const spend = s.costUsd === null ? null : toMonth(s.costUsd);
    const surviving = toMonth(s.survivingChanges);
    const costPer =
      spend === null || s.survivingChanges === 0 ? null : cents(spend / surviving);
    return {
      setup: s.id,
      label: s.label,
      monthlySpendUsd: spend === null ? null : cents(spend),
      survivingChangesPerMonth: surviving,
      costPerSurvivingChangeUsd: costPer,
      unattendedPct: tenth(s.unattendedShare * 100),
    };
  });

  const p = promoted === null ? undefined : setups.find((s) => s.id === promoted);
  const sessionsPerMonth = assumptions.scaleSessionsPerWeek * (30 / 7);
  const canScale = p !== undefined && p.sessions > 0;

  return {
    department,
    scenario: {
      hireMonthlyUsd: cents(assumptions.engineerMonthlyLoadedUsd),
      scaleMonthlyUsd:
        canScale && p.costUsd !== null
          ? cents((p.costUsd / p.sessions) * sessionsPerMonth)
          : null,
      scaleSurvivingChangesPerMonth: canScale
        ? (p.survivingChanges / p.sessions) * sessionsPerMonth
        : null,
    },
    assumptions: { ...assumptions },
  };
}
import type { buildBook } from "./book";

type Book = ReturnType<typeof buildBook>;
type Diff = { path: string; sent: unknown; got: unknown };
type Client = { call(tool: string, args: Record<string, unknown>): Promise<unknown> };

const TOLERANCE = 0.005;

function flatten(v: unknown, path: string, out: Map<string, unknown>): void {
  if (Array.isArray(v)) {
    if (v.length === 0) out.set(path, v);
    v.forEach((x, i) => flatten(x, `${path}[${i}]`, out));
  } else if (v !== null && typeof v === "object") {
    const keys = Object.keys(v);
    if (keys.length === 0) out.set(path, v);
    for (const k of keys) flatten((v as Record<string, unknown>)[k], path ? `${path}.${k}` : k, out);
  } else {
    out.set(path, v);
  }
}

function same(a: unknown, b: unknown): boolean {
  if (typeof a === "number" && typeof b === "number") return Math.abs(a - b) <= TOLERANCE;
  if (Array.isArray(a) && Array.isArray(b)) return a.length === 0 && b.length === 0;
  if (a !== null && b !== null && typeof a === "object" && typeof b === "object") {
    return Object.keys(a).length === 0 && Object.keys(b).length === 0;
  }
  return a === b;
}

export function diffBook(sent: Book, readback: Book): Diff[] {
  const s = new Map<string, unknown>();
  const g = new Map<string, unknown>();
  flatten(sent, "", s);
  flatten(readback ?? {}, "", g);
  const paths = [...s.keys(), ...[...g.keys()].filter((p) => !s.has(p))];
  const diffs: Diff[] = [];
  for (const path of paths) {
    const a = s.get(path);
    const b = g.get(path);
    if (!s.has(path) || !g.has(path) || !same(a, b)) diffs.push({ path, sent: a, got: b });
  }
  return diffs;
}

export async function writeBook(
  book: Book,
  client: Client,
  opts: { retries?: number } = {},
): Promise<{ ok: boolean; attempts: number; diffs: Diff[] }> {
  const maxAttempts = 1 + Math.max(0, opts.retries ?? 1);
  let diffs: Diff[] = [];
  let attempts = 0;
  while (attempts < maxAttempts) {
    attempts++;
    try {
      await client.call("edit_table_blocks", { book });
      const res = (await client.call("inspect_table_blocks", {})) as { book?: Book } | null | undefined;
      diffs = diffBook(book, (res?.book ?? {}) as Book);
      if (diffs.length === 0) return { ok: true, attempts, diffs };
    } catch (e) {
      diffs = [{ path: "$error", sent: undefined, got: e instanceof Error ? e.message : String(e) }];
    }
  }
  return { ok: false, attempts, diffs };
}
// The /book page's data helper. It reads the AI-workforce book that `roster book --write` publishes to
// reports/self/book.json (the prebuild copies reports/ into public/data). Money arrives in USD and shares
// arrive in [0, 1]; the page shows "$1,234.56" and "42.0%". A missing or unreadable file is an empty state.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

/** One row of the department table, already formatted for display. */
export interface BookRow {
  setup: string;
  label: string;
  monthly: string;
  perChange: string;
  unattended: string;
}

export interface Book {
  rows: BookRow[];
  scenario: { hire: string; scale: string } | null;
  shareUrl: string | null;
}

/** The empty state: no book.json published yet. */
export const emptyBook = (): Book => ({ rows: [], scenario: null, shareUrl: null });

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

const text = (v: unknown): string | null => (typeof v === "string" && v !== "" ? v : null);

/** Money, two decimals with thousands separators: 1234.56 -> "$1,234.56". Missing or non-numeric is "n/a". */
export const money = (v: unknown): string =>
  typeof v === "number" && Number.isFinite(v)
    ? `$${v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
    : "n/a";

/** A share in [0, 1] becomes a percent: 0.42 -> "42.0%". A value above 1 is already a percent. Else "n/a". */
export const percent = (v: unknown): string => {
  if (typeof v !== "number" || !Number.isFinite(v)) return "n/a";
  return `${(Math.abs(v) <= 1 ? v * 100 : v).toFixed(1)}%`;
};

/** The unattended figure: a yes/no flag, a share, an already-computed percent, or "n/a". */
const unattendedText = (v: unknown): string => {
  if (typeof v === "boolean") return v ? "yes" : "no";
  if (text(v)) return v as string;
  return percent(v);
};

const firstArray = (...vals: unknown[]): unknown[] => {
  for (const v of vals) if (Array.isArray(v)) return v;
  return [];
};

/** One formatted row, keyed as the page reads it or as src/cfo/book.ts writes the department. */
function rowOf(raw: Record<string, unknown>): BookRow {
  const setup = text(raw.setup) ?? text(raw.setup_id) ?? "";
  // The builder calls cost per surviving change money (costPerSurvivingChangeUsd); a page-shaped book may
  // instead carry `perChange` as a share, which reads as a percent. Each key keeps its own meaning.
  const perChange = raw.perChange !== undefined ? percent(raw.perChange) : money(raw.costPerSurvivingChangeUsd);
  return {
    setup,
    label: text(raw.label) ?? setup,
    monthly: money(raw.monthly ?? raw.monthlySpendUsd ?? raw.spend_usd),
    perChange,
    unattended: unattendedText(raw.unattended ?? raw.unattendedPct),
  };
}

function scenarioOf(v: unknown): Book["scenario"] {
  if (!isRecord(v)) return null;
  return { hire: money(v.hire ?? v.hireMonthlyUsd), scale: money(v.scale ?? v.scaleMonthlyUsd) };
}

/** The book's share link, kept only when it is an https URL on cfo.ai. Anything else is null. */
export function shareUrlOf(v: unknown): string | null {
  if (typeof v !== "string") return null;
  let url: URL;
  try {
    url = new URL(v);
  } catch {
    return null;
  }
  const host = url.hostname.toLowerCase();
  if (url.protocol !== "https:") return null;
  if (host !== "cfo.ai" && !host.endsWith(".cfo.ai")) return null;
  return v;
}

/** Accepts a parsed book.json. Anything else (null, a string, an array) gives the empty state. */
export function loadBook(json: unknown): Book {
  if (!isRecord(json)) return emptyBook();
  const rows = firstArray(json.rows, json.department, json.setups)
    .filter(isRecord)
    .map(rowOf);
  return { rows, scenario: scenarioOf(json.scenario), shareUrl: shareUrlOf(json.shareUrl) };
}

/** Where the book lands in the web data dir: reports/self/book.json -> public/data/self/book.json. */
export const bookPath = (dataDir: string): string => join(dataDir, "self", "book.json");

/** loadBook over public/data/self/book.json. Absent, unreadable or malformed JSON is the empty state. */
export function loadBookFromData(dataDir: string = join(process.cwd(), "public", "data")): Book {
  const file = bookPath(dataDir);
  if (!existsSync(file)) return emptyBook();
  try {
    return loadBook(JSON.parse(readFileSync(file, "utf8")));
  } catch {
    return emptyBook();
  }
}
